import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import type { PhiOverviewViewState } from '../../../types';
import {
  PHI_OVERVIEW_EMPTY_DESCRIPTION_I18N_ID,
  PHI_OVERVIEW_EMPTY_TITLE_I18N_ID,
  PHI_OVERVIEW_ERROR_DESCRIPTION_I18N_ID,
  PHI_OVERVIEW_ERROR_TITLE_I18N_ID,
} from '../constants';

export function usePhiOverviewSectionUi(view: PhiOverviewViewState) {
  const { formatMessage } = useIntl();

  const stateMessage = useMemo(() => {
    if (view === 'error') {
      return {
        title: formatMessage({ id: PHI_OVERVIEW_ERROR_TITLE_I18N_ID }),
        description: formatMessage({
          id: PHI_OVERVIEW_ERROR_DESCRIPTION_I18N_ID,
        }),
      };
    }

    if (view === 'empty') {
      return {
        title: formatMessage({ id: PHI_OVERVIEW_EMPTY_TITLE_I18N_ID }),
        description: formatMessage({
          id: PHI_OVERVIEW_EMPTY_DESCRIPTION_I18N_ID,
        }),
      };
    }

    return undefined;
  }, [formatMessage, view]);

  return { stateMessage };
}
